// Assembles registry.json from registry/*.json (loaders*.json: loaders.json is
// the loader-kit item, the rest are generated by scripts/loaders.mjs), then
// (unless --check) runs `shadcn build` into public/r, which the docs site serves
// beside the other packages' items. The loaders install at
// components/youj/loaders/, and their imports from @youj/core become
// youj-core's files (scripts/source-registry.mjs).
//
//   node scripts/build-registry.mjs          write registry.json + public/r
//   node scripts/build-registry.mjs --check  validate only; exit 1 on problems
import { join } from 'node:path'
import { buildSourceRegistry } from '../../../scripts/source-registry.mjs'

buildSourceRegistry(join(import.meta.dirname, '..'), 'youj-loaders')
